import { test, expect } from '@playwright/test';

test.describe('Date Picker Keyboard Operability', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/date-picker');
  });

  test('should open date picker using arrow keys and select dates using tab and enter', async ({ page }) => {
    // Verify date picker is not visible initially
    const datePicker = page.getByRole('dialog', { name: /date picker/i });
    await expect(datePicker).not.toBeVisible();

    // Open date picker using right arrow key
    const openButton = page.getByRole('button', { name: /open/i });
    await openButton.click();
    await page.keyboard.press('ArrowRight');
    await expect(datePicker).toBeVisible();

    // Verify calendar is visible
    const calendar = page.getByRole('region', { name: /calendar/i });
    await expect(calendar).toBeVisible();

    // Select first day using tab
    const firstDay = page.getByRole('option', { name: /1/i });
    await firstDay.click();

    // Verify first date is selected
    const selectedDate = page.getByText(/1/i);
    await expect(selectedDate).toBeVisible();

    // Select second day using tab
    const secondDay = page.getByRole('option', { name: /2/i });
    await secondDay.click();

    // Verify second date is selected
    const selectedDate2 = page.getByText(/2/i);
    await expect(selectedDate2).toBeVisible();

    // Select third day using tab
    const thirdDay = page.getByRole('option', { name: /3/i });
    await thirdDay.click();

    // Verify third date is selected
    const selectedDate3 = page.getByText(/3/i);
    await expect(selectedDate3).toBeVisible();

    // Close date picker using Escape key
    await page.keyboard.press('Escape');
    await expect(datePicker).not.toBeVisible();
  });

  test('should handle keyboard navigation and selection of multiple dates', async ({ page }) => {
    // Open date picker using right arrow key
    const openButton = page.getByRole('button', { name: /open/i });
    await openButton.click();
    await page.keyboard.press('ArrowRight');
    await expect(page.getByRole('dialog', { name: /date picker/i })).toBeVisible();

    // Navigate to third day using tab
    const thirdDay = page.getByRole('option', { name: /3/i });
    await thirdDay.click();

    // Verify third date is selected
    const selectedDate = page.getByText(/3/i);
    await expect(selectedDate).toBeVisible();

    // Navigate to second day using tab
    const secondDay = page.getByRole('option', { name: /2/i });
    await secondDay.click();

    // Verify second date is selected
    const selectedDate2 = page.getByText(/2/i);
    await expect(selectedDate2).toBeVisible();

    // Navigate to first day using tab
    const firstDay = page.getByRole('option', { name: /1/i });
    await firstDay.click();

    // Verify first date is selected
    const selectedDate1 = page.getByText(/1/i);
    await expect(selectedDate1).toBeVisible();

    // Select fourth day using tab
    const fourthDay = page.getByRole('option', { name: /4/i });
    await fourthDay.click();

    // Verify fourth date is selected
    const selectedDate4 = page.getByText(/4/i);
    await expect(selectedDate4).toBeVisible();

    // Close date picker using Escape key
    await page.keyboard.press('Escape');
    await expect(page.getByRole('dialog', { name: /date picker/i })).not.toBeVisible();
  });
});
